// Package database stores issues, contacts and settings in SQLite. The
// queries are generated by sqlc from query.sql.
package database

import (
	"context"
	"database/sql"
	_ "embed"
	"fmt"
)

//go:generate sqlc generate

//go:embed schema.sql
var schema string

// Migrate creates the tables that do not exist yet.
func Migrate(ctx context.Context, db *sql.DB) error {
	if _, err := db.ExecContext(ctx, schema); err != nil {
		return fmt.Errorf("create tables: %w", err)
	}
	return nil
}
